head.script:
scwin.g_hdcom_isur_cd;
scwin.g_hdcom_com_abbrv;
scwin.g_hdcom_lm_mkt_tp_cd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        scwin.getParentValue();
        await scwin.init();
        await scwin.readSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF33021.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    txb_HDCOM_ISUR_CD.setValue(scwin.g_hdcom_isur_cd);
    txb_HDCOM_COM_ABBRV.setValue(scwin.g_hdcom_com_abbrv);
    txb_HDCOM_LM_MKT_TP_CD.setValue(scwin.g_hdcom_lm_mkt_tp_cd);
    await scwin.subcomReadSync();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name cmb_SUBCOM_ISUR_CD_OnCloseUp
 * @description cmb SUBCOM ISUR CD On Close Up 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_SUBCOM_ISUR_CD_OnCloseUp = async function() {
    try {
        await scwin.readSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF33021.cmb_SUBCOM_ISUR_CD_OnCloseUp" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF33021.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF33021.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF33021.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_SUBCOM_OnLoadError
 * @description dts_SUBCOM 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_SUBCOM_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_SUBCOM);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF33021.dts_SUBCOM_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF33021.xml", SCREN_PROCS_TP_CD_07, '');
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "상장자회사 신청내역 ", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF33021.btn_Excel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name readSync
 * @description read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function() {
    url += "&SCREN_ID=" + "ULDSTF33021.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/LnkDisclsApplCorp.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name subcomReadSync
 * @description subcom Read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.subcomReadSync = async function() {
    url += "&SCREN_ID=" + "ULDSTF33021.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_SUBCOM",
        action : "/LnkDisclsApplCorp.do",
        ref : "",
        target : "dts_SUBCOM=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParentValue
 * @description get Parent Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.getParentValue = function() {
    scwin.g_hdcom_isur_cd = $c.frame.path("../").scwin.g_hdcom_isur_cd;
    scwin.g_hdcom_com_abbrv = $c.frame.path("../").scwin.g_hdcom_com_abbrv;
    scwin.g_hdcom_lm_mkt_tp_cd = $c.frame.path("../").scwin.g_hdcom_lm_mkt_tp_cd;
};
